<?php
declare(strict_types=1);
$pageUrl = static fn (int $number): string => app_url('/admin/messages?' . http_build_query(['q' => $filters['q'], 'status' => $filters['status'], 'page' => $number]));
?>
<div><h1 class="text-3xl font-extrabold text-brand-navy">Contact messages</h1><p class="mt-2 text-slate-600"><?= e_value((string) $result['total']) ?> messages.</p></div>
<div class="mt-4"><a class="inline-flex rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-brand-navy hover:bg-slate-50" href="<?= e($exportUrl) ?>">Export filtered CSV</a></div>
<form class="mt-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 sm:grid-cols-[1fr_220px_auto_auto]" action="<?= e(app_url('/admin/messages')) ?>" method="get">
  <label><span class="block text-xs font-bold text-slate-600">Search</span><input class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" name="q" type="search" maxlength="120" value="<?= e_value($filters['q']) ?>" placeholder="Name, phone, subject or message"></label>
  <label><span class="block text-xs font-bold text-slate-600">Status</span><select class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" name="status"><option value="">All messages</option><?php foreach ($statuses as $status): ?><option value="<?= e($status) ?>"<?= $filters['status'] === $status ? ' selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label>
  <button class="self-end rounded-lg bg-brand-navy px-4 py-2.5 text-sm font-bold text-white" type="submit">Filter</button><a class="self-end rounded-lg border border-slate-300 px-4 py-2.5 text-center text-sm font-bold" href="<?= e(app_url('/admin/messages')) ?>">Clear</a>
</form>
<section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
  <?php if ($result['items'] === []): ?><p class="p-10 text-center text-sm text-slate-500">No messages found.</p><?php else: ?><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Sender</th><th class="px-5 py-3">Subject / message</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Received</th><th class="px-5 py-3"></th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($result['items'] as $message): ?><tr><td class="px-5 py-4"><span class="font-bold"><?= e_value($message['name']) ?></span><span class="mt-1 block text-xs text-slate-500"><?= e_value($message['phone'] ?: $message['email'] ?: 'No reply details') ?></span></td><td class="max-w-sm px-5 py-4"><span class="font-semibold"><?= e_value($message['subject'] ?: 'General inquiry') ?></span><span class="mt-1 block truncate text-xs text-slate-500"><?= e_value($message['message']) ?></span></td><td class="px-5 py-4"><?= e_value(ucfirst($message['status'])) ?></td><td class="px-5 py-4 text-xs"><?= e_value($message['created_at']) ?></td><td class="px-5 py-4"><a class="font-bold text-brand-red hover:underline" href="<?= e(app_url('/admin/messages/' . (int) $message['id'])) ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<?php if ($result['pages'] > 1): ?><nav class="mt-5 flex justify-between text-sm"><span>Page <?= e_value((string) $result['page']) ?> of <?= e_value((string) $result['pages']) ?></span><span class="flex gap-2"><?php if ($result['page'] > 1): ?><a class="rounded-lg border bg-white px-4 py-2" href="<?= e($pageUrl($result['page'] - 1)) ?>">Previous</a><?php endif; ?><?php if ($result['page'] < $result['pages']): ?><a class="rounded-lg border bg-white px-4 py-2" href="<?= e($pageUrl($result['page'] + 1)) ?>">Next</a><?php endif; ?></span></nav><?php endif; ?>
